*/
scwin.grd_ReportDataList_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_ReportDataList');
        if (!dl) { console.error('[sdd] 행 동작 대상 목록 없음: dlt_ReportDataList'); return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        if (columnId === "__rowAct") { if (r["integSrchYn"] === 'N') { if (typeof scwin.applyIntegSrchWord === 'function') { scwin.applyIntegSrchWord(r["formcd2"], r["formKorNm"], r["ldMktTpCd"], r["formAdmInstTpCd"]); } else { console.error('[sdd] 행 동작 미정의: scwin.applyIntegSrchWord (열 ?)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.applyIntegSrchWord'); } return; } return; } 
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_ReportDataList.oncellclick' });
    }
};


