/**
 * @method
 * @name scwin.tx_searchForm
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_searchForm = async function () {
    const sbmOptions = {
        id: "tx_searchForm",
        method: "post",
        action: "/ods/integsrch.do",
        ref: "dma_searchFormReq",
        target: "dlt_ReportDataList=body.content",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldstf70030.tx_searchForm" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    const rj = res && res.responseJSON;
    const tot = rj && (rj["pageCount"] != null ? rj["pageCount"] : (rj.body && rj.body["pageCount"]));
    if (tot != null && tot !== "") {
        $c.util.getComponent("krxpage_pagenavigator_83").setCount(Math.ceil(Number(tot) / 10));
    }
    return res;
};


